//  for the callback interface
int iut_randombytes(uint8_t *x, size_t xlen) {
  // aes_256ctr_xof(&iut_drbg, x, xlen);
  return 0;
}
// Función empleada para imprimir los valores de las cadenas de caracteres en el
// fichero fh.
static void kat_hex(const char *label, const uint8_t *x, size_t xlen) {
  size_t i;
  neorv32_uart0_printf("%s = ", label);
  for (i = 0; i < xlen; i++) {
    neorv32_uart0_printf("%X", x[i]);
  }
  neorv32_uart0_printf("\n");
}

