//  test targets

const slh_param_t *test_iut[] = {
    &slh_dsa_shake_128s,   &slh_dsa_shake_128f, &slh_dsa_shake_192s,
    &slh_dsa_shake_192f,   &slh_dsa_shake_256s, &slh_dsa_shake_256f,
    &slh_dsa_shake_128_24, &slh_dsa_ascon_128s, NULL};

int main(void) {

  neorv32_rte_setup();
  neorv32_uart0_setup(BAUD_RATE, 0);
  if (neorv32_gptmr_available() == 0) {
    neorv32_uart0_puts("ERROR! General purpose timer not implemented!\n");
    return 1;
  }
  neorv32_uart0_puts("SLH-DSA in NEORV32\n");
  int fail = 0;
  int iut_n = 6;

  uint8_t buf[200] = {0};
  uint8_t ascon_msg[3] = {0x00,0x01,0x02};
  // if  (argc == 2 &&
  //     (iut_n = atoi(argv[1])) >= 0 &&
  //     iut_n < 12) {
  neorv32_uart0_printf("SHAKE and ASCON TEST\n");
  memset(buf, 0x00, 200);
  memcpy(buf, "abc\x1F", 4);              //  pad: 0x1F=SHAKE, 0x06=SHA-3
  buf[200 - 2*32 - 1] = 0x80;             //  rate/capacity for 256
  keccak_f1600(buf);
  fail += rvkat_chku32("shake256", 0x07C97065, rvkat_cksum(buf, 32));
  uint8_t asconBuf[16];
  memset(asconBuf, 0x00, 16);
  memcpy(asconBuf,ascon_msg,3); 
  crypto_hash(asconBuf,asconBuf,3);
  neorv32_uart0_printf("The ASCONXOF-128 digest is: 0x");
  for (uint8_t i=0; i<16; i++) {
    neorv32_uart0_printf("%X",asconBuf[i]); 
  }
  neorv32_uart0_printf("\n");
  fail += rvkat_chku32("asconxof-128", 0x4116e853, rvkat_cksum(asconBuf, 16));
  neorv32_uart0_printf("kat_test entry point\n");
  neorv32_uart0_printf("SLH-DSA algorithm: %s\n", slh_alg_id(test_iut[iut_n]));
  fail += kat_test(test_iut[iut_n], 1, iut_n);
  // } else {
  //     for (iut_n = 0; test_iut[iut_n] != NULL; iut_n++) {
  //         fail += kat_test(test_iut[iut_n], KATNUM);
  //     }
  // }

  neorv32_uart0_printf("[INFO] test_slh_dsa() fail= %d\n", fail);

  return fail;
}

